class BloomFilter:
    """
    A Bloom Filter implementation that uses two layers of hash functions to improve key distribution
    and reduce collisions. It calculates the optimal bit array size and number of hash functions based
    on the expected items and false positive rate, similarly to traditional methods, but uses a different 
    approach to manage hash generation and indexing.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array
        self.size = self._calculate_bit_array_size(expected_items, false_positive_rate)

        # Calculate the optimal number of hash functions
        self.hash_count = self._calculate_hash_count(self.size, expected_items)

        # Initialize a bit array using a bytearray
        self.bit_array = bytearray((0,) * ((self.size + 7) // 8))

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array based on items and false positive rate."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def _calculate_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int(m / n * math.log(2)))

    def _get_hash_indices(self, item: str) -> list:
        """Generate hash indices for the given item."""
        indices = []
        for i in range(self.hash_count):
            hash_val = hashlib.md5((item + str(i)).encode()).hexdigest()
            index = int(hash_val, 16) % self.size
            indices.append(index)
        return indices

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for index in self._get_hash_indices(item):
            byte_index = index // 8
            bit_position = index % 8
            self.bit_array[byte_index] |= (1 << bit_position)

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        return all(
            self.bit_array[index // 8] & (1 << (index % 8)) != 0 
            for index in self._get_hash_indices(item)
        )

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that leverages a variable-sized bit array to dynamically adjust
    its capacity as necessary based on the number of insertions. This approach allows for a more
    memory-efficient representation and aims to reduce the chance of high false positive rates by
    scaling the bit array size when a certain threshold is reached.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.bit_array_size = self._calculate_initial_bit_array_size(expected_items, false_positive_rate)
        self.bit_array = [0] * self.bit_array_size
        self.num_hash_functions = self._calculate_number_of_hashes(self.bit_array_size, expected_items)
        self.current_item_count = 0

    def _calculate_initial_bit_array_size(self, n: int, p: float) -> int:
        """Calculate an initial bit array size based on expected items and desired false positive rate."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def _calculate_number_of_hashes(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int(m / n * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash index for the given item using a seed to simulate multiple hash functions."""
        hash_result = hashlib.md5((item + str(seed)).encode()).hexdigest()
        return int(hash_result, 16) % self.bit_array_size

    def _resize_bit_array(self):
        """Resize the bit array if the current item count exceeds expected items to maintain efficiency."""
        if self.current_item_count >= self.expected_items:
            self.bit_array_size *= 2
            new_bit_array = [0] * self.bit_array_size

            for i in range(len(self.bit_array)):
                if self.bit_array[i]:
                    for j in range(self.num_hash_functions):
                        new_index = self._hash(str(i), j) % self.bit_array_size
                        new_bit_array[new_index] = 1

            self.bit_array = new_bit_array
            self.num_hash_functions = self._calculate_number_of_hashes(self.bit_array_size, self.current_item_count)

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter, resizing if necessary."""
        self._resize_bit_array()
        for i in range(self.num_hash_functions):
            index = self._hash(item, i)
            self.bit_array[index] = 1
        self.current_item_count += 1

    def contains(self, item: str) -> bool:
        """Check if the item is possibly in the Bloom filter."""
        return all(self.bit_array[self._hash(item, i)] for i in range(self.num_hash_functions))
